class Solution {
public:
    vector<int> minReverseOperations(int n, int p, vector<int>& banned, int k) {
        vector<int> ans(n, -1);
        vector<vector<int>> starts(2), par(2);
        for (int q = 0; q < 2; q++) {
            for (int v = q; v < n; v += 2) starts[q].push_back(v);
            par[q].resize(starts[q].size() + 1);
            iota(par[q].begin(), par[q].end(), 0);
        }
        function<int(int,int)> find = [&](int q, int i) {
            while (par[q][i] != i) { par[q][i] = par[q][par[q][i]]; i = par[q][i]; }
            return i;
        };
        auto use = [&](int q, int i) { par[q][i] = i + 1; };
        for (int b : banned) use(b & 1, b >> 1);
        ans[p] = 0;
        queue<int> dq;
        dq.push(p);
        while (!dq.empty()) {
            int x = dq.front(); dq.pop();
            int d = ans[x];
            int lo = 2 * max(0, x - k + 1) + k - 1 - x;
            int hi = 2 * min(x, n - k) + k - 1 - x;
            int q = lo & 1;
            int i = find(q, (lo - q) / 2), end = (hi - q) / 2;
            while (i <= end) {
                int y = starts[q][i];
                ans[y] = d + 1;
                dq.push(y);
                use(q, i);
                i = find(q, i);
            }
        }
        return ans;
    }
};

