class Solution {
    public int[] minReverseOperations(int n, int p, int[] banned, int k) {
        int[] ans = new int[n];
        Arrays.fill(ans, -1);
        List<List<Integer>> starts = new ArrayList<>();
        List<List<Integer>> par = new ArrayList<>();
        for (int q = 0; q < 2; q++) {
            List<Integer> s = new ArrayList<>();
            for (int v = q; v < n; v += 2) s.add(v);
            starts.add(s);
            List<Integer> pr = new ArrayList<>();
            for (int i = 0; i <= s.size(); i++) pr.add(i);
            par.add(pr);
        }
        for (int b : banned) par.get(b & 1).set(b >> 1, (b >> 1) + 1);
        int[] findPar = null;
        ans[p] = 0;
        Deque<Integer> dq = new ArrayDeque<>();
        dq.add(p);
        while (!dq.isEmpty()) {
            int x = dq.poll(), d = ans[x];
            int lo = 2 * Math.max(0, x - k + 1) + k - 1 - x;
            int hi = 2 * Math.min(x, n - k) + k - 1 - x;
            int q = lo & 1;
            List<Integer> pr = par.get(q), st = starts.get(q);
            int i = find(pr, (lo - q) / 2), end = (hi - q) / 2;
            while (i <= end) {
                int y = st.get(i);
                ans[y] = d + 1;
                dq.add(y);
                pr.set(i, i + 1);
                i = find(pr, i);
            }
        }
        return ans;
    }
    private int find(List<Integer> par, int i) {
        while (par.get(i) != i) {
            par.set(i, par.get(par.get(i)));
            i = par.get(i);
        }
        return i;
    }
}

