var minReverseOperations = function(n, p, banned, k) {
    const ans = new Array(n).fill(-1);
    const starts = [[], []], par = [[], []];
    for (let q = 0; q < 2; q++) {
        for (let v = q; v < n; v += 2) starts[q].push(v);
        for (let i = 0; i <= starts[q].length; i++) par[q].push(i);
    }
    const find = (q, i) => {
        while (par[q][i] !== i) { par[q][i] = par[q][par[q][i]]; i = par[q][i]; }
        return i;
    };
    for (const b of banned) par[b & 1][b >> 1] = (b >> 1) + 1;
    ans[p] = 0;
    const dq = [p];
    while (dq.length) {
        const x = dq.shift(), d = ans[x];
        const lo = 2 * Math.max(0, x - k + 1) + k - 1 - x;
        const hi = 2 * Math.min(x, n - k) + k - 1 - x;
        const q = lo & 1;
        let i = find(q, (lo - q) / 2);
        const end = (hi - q) / 2;
        while (i <= end) {
            const y = starts[q][i];
            ans[y] = d + 1;
            dq.push(y);
            par[q][i] = i + 1;
            i = find(q, i);
        }
    }
    return ans;
};
